files.content:
.sidebar{
  position:sticky;
  top:0;
  height:100vh;
  border-right:var(--bw-1) solid var(--obsidian-700);
  background:var(--surface-bar);
  backdrop-filter:blur(var(--blur-bar));
  padding:var(--s-6) var(--s-5);
  display:flex;
  flex-direction:column;
  gap:var(--s-8);
  overflow-y:auto;
  z-index:var(--z-sticky);
}
.nav-group{
  display:flex;
  flex-direction:column;
  gap:var(--s-1);
  position:relative;
}
.nav-indicator{
  position:absolute;
  left:calc(-1 * var(--s-5));
  top:0;
  width:var(--bw-2);
  height:var(--s-4);
  background:var(--primary-500);
  border-radius:var(--r-xs);
  box-shadow:0 0 var(--s-3) var(--primary-500);
  transform:translateY(0);
  transition:transform var(--d-quick) var(--ease-standard), opacity var(--d-quick) var(--ease-standard);
  opacity:0;
  pointer-events:none;
  z-index:2;
}
.nav-group.has-active .nav-indicator{
  opacity:1;
}
@media (prefers-reduced-motion: reduce){
  .nav-indicator{
    transition:none;
  }
}
.nav-label{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  text-transform:uppercase;
  color:var(--obsidian-400);
  padding:0 var(--s-3);
  margin-bottom:var(--s-2);
  display:flex;
  align-items:center;
  gap:var(--s-2);
}
.nav-label::before{
  content:"";
  width:4px;
  height:4px;
  background:var(--primary-500);
  border-radius:1px;
}
.nav-item{
  outline-offset:var(--s-0-5);
  display:flex;
  align-items:center;
  gap:var(--s-3);
  padding:var(--s-2) var(--s-3);
  border-radius:var(--r-md);
  font-size:var(--t-small);
  color:var(--obsidian-200);
  cursor:pointer;
  transition:all var(--d-quick) var(--ease-standard);
  position:relative;
  user-select:none;
}
.nav-item .num{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  color:var(--obsidian-400);
  letter-spacing:var(--tr-mono);
  min-width:calc(var(--s-4) + var(--s-0-5));
}
.nav-item:hover{
  color:var(--obsidian-050);
}
.nav-item:active{
  color:var(--obsidian-300);
}
.nav-item.active{
  background:linear-gradient(180deg, color-mix(in srgb, var(--primary-500) calc(var(--tint-fill) * 100%), transparent), color-mix(in srgb, var(--secondary-500) calc(var(--tint-faint) * 100%), transparent));
  color:var(--obsidian-100);
  border:var(--bw-1) solid color-mix(in srgb, var(--primary-500) calc(var(--tint-glow) * 100%), transparent);
  padding:var(--s-2) var(--s-3);
}
.nav-item.active .num{
  color:var(--primary-400);
}
.nav-item.active::after{
  display:none;
}
.sidebar-footer{
  margin-top:auto;
  padding-top:var(--s-5);
  border-top:var(--bw-1) solid var(--obsidian-800);
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  color:var(--obsidian-400);
  text-transform:uppercase;
  display:flex;
  flex-direction:column;
  gap:var(--s-1);
}
.nav-item:focus-visible, .menu-toggle:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:var(--focus-offset);
  box-shadow:var(--ring-halo);
}
.menu-toggle{
  display:none;
  width:40px;
  height:40px;
  border:var(--bw-1) solid var(--obsidian-700);
  border-radius:var(--r-md);
  background:var(--obsidian-850);
  padding:0;
  align-items:center;
  justify-content:center;
  color:var(--obsidian-100);
  cursor:pointer;
  transition:border-color var(--d-quick) var(--ease-standard), background var(--d-quick) var(--ease-standard);
  flex:0 0 auto;
}
.menu-toggle:hover{
  border-color:var(--primary-500);
}
.menu-toggle-bars{
  display:inline-flex;
  flex-direction:column;
  gap:var(--s-1);
  width:18px;
}
.menu-toggle-bars span{
  display:block;
  height:2px;
  background:currentColor;
  border-radius:1px;
  transition:transform var(--d-quick) var(--ease-standard), opacity var(--d-quick) var(--ease-standard);
  transform-origin:center;
}
.menu-toggle[aria-expanded="true"] .menu-toggle-bars span:nth-child(1){
  transform:translateY(6px) rotate(45deg);
}
.menu-toggle[aria-expanded="true"] .menu-toggle-bars span:nth-child(2){
  opacity:0;
}
.menu-toggle[aria-expanded="true"] .menu-toggle-bars span:nth-child(3){
  transform:translateY(-6px) rotate(-45deg);
}
.sidebar-scrim{
  display:none;
  position:fixed;
  inset:0;
  background:var(--scrim);
  backdrop-filter:blur(var(--blur-veil));
  z-index:var(--z-scrim);
  opacity:0;
  transition:opacity var(--d-quick) var(--ease-standard);
}
@media (max-width: 900px){
  .menu-toggle{
    display:inline-flex;
  }
  .sidebar{
    position:fixed;
    top:0;
    left:0;
    width:min(86vw, 320px);
    height:100vh;
    transform:translateX(-100%);
    transition:transform var(--d-base) var(--ease-decel);
    z-index:var(--z-menu);
    border-right:var(--bw-1) solid var(--obsidian-800);
    box-shadow:8px 0 32px color-mix(in srgb, var(--obsidian-950) calc(var(--tint-edge-deep) * 100%), transparent);
  }
  .nav-item.active::after{
    display:none;
  }
}
.navbar{
  container-type:inline-size;
  position:sticky;
  top:0;
  z-index:var(--z-sticky);
  display:flex;
  align-items:stretch;
  gap:var(--s-8);
  min-block-size:var(--s-12);
  padding-inline:0;
  background:transparent;
  border-radius:0;
  color:var(--obsidian-100);
}
.navbar::before{
  content:"";
  position:absolute;
  inset:0 0 calc(-1 * var(--s-6));
  z-index:-1;
  pointer-events:none;
  background:linear-gradient(var(--surface-bar), transparent);
  backdrop-filter:blur(var(--blur-bar));
  -webkit-backdrop-filter:blur(var(--blur-bar));
  -webkit-mask-image:linear-gradient(black 55%, transparent);
  mask-image:linear-gradient(black 55%, transparent);
}
.navbar-brand{
  padding-inline-start:var(--s-6);
  display:flex;
  align-items:center;
  gap:var(--s-3);
  flex:none;
  color:var(--obsidian-100);
  font-size:var(--t-body);
  font-weight:700;
  letter-spacing:var(--tr-snug);
  text-decoration:none;
}
.navbar-nav{
  display:flex;
  align-items:stretch;
}
.navbar-list{
  display:flex;
  align-items:stretch;
  margin:0;
  padding:0;
  list-style:none;
}
.navbar-list > li{
  display:flex;
}
.navbar-item{
  display:inline-flex;
  flex-direction:column;
  justify-content:center;
  align-items:center;
  padding-inline:var(--s-4);
  color:var(--obsidian-200);
  font-size:var(--t-small);
  font-weight:500;
  text-decoration:none;
  white-space:nowrap;
  cursor:pointer;
  transition:color var(--d-quick) var(--ease-standard);
}
.navbar-item::after{
  content:attr(data-label);
  height:0;
  overflow:hidden;
  visibility:hidden;
  font-weight:600;
  pointer-events:none;
}
.navbar-item:hover{
  color:var(--obsidian-050);
}
.navbar-item:active{
  color:var(--obsidian-300);
}
.navbar-item[aria-current="page"]{
  color:var(--primary-400);
  font-weight:600;
}
.navbar-item[aria-current="page"]:hover{
  color:var(--primary-400);
}
.navbar-item:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:calc(-1 * var(--focus-width));
  box-shadow:var(--ring-halo);
}
.navbar-end{
  padding-inline-end:var(--s-6);
  display:flex;
  align-items:center;
  gap:var(--s-3);
  margin-left:auto;
  flex:none;
}
.navbar-toggle{
  display:none;
}
.navbar-end > .navbar-toggle{
  margin-inline-end:calc((var(--icon-sm) - var(--s-10)) / 2);
}
@media (pointer:coarse){
  .navbar-end > .navbar-toggle{
    margin-inline-end:calc((var(--icon-sm) - var(--target-touch)) / 2);
  }
}
@container (max-width: 720px){
  .navbar-nav{
    display:none;
  }
  .navbar-toggle{
    display:inline-flex;
  }
}
.navbar-floating{
  container-type:normal;
  top:var(--s-4);
  margin:var(--s-4) auto 0;
  width:max-content;
  max-width:calc(100% - var(--s-8));
  gap:var(--s-4);
  background:var(--surface-bar);
  backdrop-filter:blur(var(--blur-bar));
  -webkit-backdrop-filter:blur(var(--blur-bar));
  border:var(--bw-1) solid var(--border-subtle);
  border-radius:var(--r-full);
  box-shadow:var(--sh-3);
}
.navbar-floating::before{
  content:none;
}
.navbar-floating .navbar-brand{
  padding-inline-start:var(--s-2);
}
.navbar-floating .navbar-end{
  padding-inline-end:var(--s-2);
}
.navbar-floating .navbar-item{
  padding-inline:var(--s-3);
}
@media (max-width: 720px){
  .navbar-floating{
    position:relative;
    top:auto;
    margin:0;
    width:auto;
    max-width:none;
    background:transparent;
    backdrop-filter:none;
    -webkit-backdrop-filter:none;
    border:0;
    border-radius:0;
    box-shadow:none;
  }
  .navbar-floating .navbar-brand{
    padding-inline-start:var(--s-4);
  }
  .navbar-floating .navbar-end{
    padding-inline-end:var(--s-4);
  }
  .navbar-floating .navbar-nav{
    position:fixed;
    z-index:var(--z-sticky);
    left:0;
    right:0;
    bottom:var(--s-4);
    margin:0 auto env(safe-area-inset-bottom);
    width:max-content;
    max-width:calc(100% - var(--s-8));
    min-block-size:var(--s-12);
    padding-inline:var(--s-2);
    background:var(--surface-bar);
    backdrop-filter:blur(var(--blur-bar));
    -webkit-backdrop-filter:blur(var(--blur-bar));
    border:var(--bw-1) solid var(--border-subtle);
    border-radius:var(--r-full);
    box-shadow:var(--sh-3);
  }
}
